STATES = {}
COOLDOWNS = {}
def get_lobby(lobby_code):
    row = DB.fetchone("SELECT lobby_data FROM party_lobbies WHERE lobby_code = %s", (lobby_code,))
    if not row:
        return None
    return json.loads(row["lobby_data"])

def set_lobby(lobby_code, lobby_dict):
    data = json.dumps(lobby_dict, ensure_ascii=False)
    DB.execute(
        "INSERT INTO party_lobbies (lobby_code, lobby_data) VALUES (%s, %s) ON DUPLICATE KEY UPDATE lobby_data = %s",
        (lobby_code, data, data)
    )

def delete_lobby(lobby_code):
    DB.execute("DELETE FROM party_lobbies WHERE lobby_code = %s", (lobby_code,))

def get_all_lobbies():
    rows = DB.fetchall("SELECT lobby_code, lobby_data FROM party_lobbies")
    return {r["lobby_code"]: json.loads(r["lobby_data"]) for r in rows}

async def cleanup_old_lobbies():
    while True:
        try:
            deleted = DB.execute_and_get_rowcount("DELETE FROM party_lobbies WHERE updated_at < NOW() - INTERVAL 2 HOUR")
            if deleted:
                print(f"[CLEANUP] {deleted} لابی قدیمی حذف شد.")
        except Exception as e:
            print(f"[CLEANUP ERROR - lobbies] {repr(e)}")
        await asyncio.sleep(1800)
