def _interpolate_log_linear(table, x):
    xs = [p[0] for p in table]
    if x <= table[0][0]:
        (x1, y1), (x2, y2) = table[0], table[1]
    elif x >= table[-1][0]:
        (x1, y1), (x2, y2) = table[-2], table[-1]
    else:
        idx = bisect.bisect_right(xs, x)
        x1, y1 = table[idx - 1]
        x2, y2 = table[idx]
    if x2 == x1:
        return y1
    t = (x - x1) / (x2 - x1)
    log_y = math.log(y1) + t * (math.log(y2) - math.log(y1))
    return max(1, math.exp(log_y))
