def _check_content_sync(name: str, system_prompt: str) -> str:
    """بررسی یک متن دلخواه از طریق API هوش مصنوعی با یک پرامپت سیستمی مشخص. خروجی: 'true' | 'false' | 'error'"""
    headers = {
        "Authorization": f"Bearer {NAME_CHECK_API_KEY}",
        "Content-Type": "application/json"
    }
    payload = {
        "model": NAME_CHECK_MODEL,
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": f"نام: {name}"}
        ],
        "temperature": 0.0,
        "max_tokens": 10
    }
    try:
        response = requests.post(NAME_CHECK_BASE_URL, headers=headers, json=payload, timeout=15)
        response.raise_for_status()
        data = response.json()
        answer = data["choices"][0]["message"]["content"].strip().lower()
        if "false" in answer:
            return "false"
        elif "true" in answer:
            return "true"
        else:
            print(f"[NAME CHECK] ambiguous response: {answer!r}")
            return "error"
    except Exception as e:
        print(f"[NAME CHECK ERROR] {repr(e)}")
        return "error"

async def check_name_ai(name: str) -> str:
    """بررسی نام بازیکن. خروجی: 'true' | 'false' | 'error'"""
    return await asyncio.to_thread(_check_content_sync, name, PLAYER_NAME_SYSTEM_PROMPT)

