# ۴. توابع تکمیلی: پیشرفت مأموریت، ارتقای سطح، جاسوسی پارتنر
# ============================================================

# --- ۴-۱. پیشرفت مأموریت‌ها ---
def update_quest_progress(player_id, action_type, value=1):
    """بروزرسانی پیشرفت مأموریت‌های فعال بر اساس نوع اقدام"""
    active_quests = DB.fetchall("""
        SELECT pq.*, q.target_type, q.target_count, q.title, q.reward_xp, q.reward_coins, q.reward_items, q.penalty_coins
        FROM player_quests pq
        JOIN quests q ON pq.quest_id = q.quest_id
        WHERE pq.player_id = %s AND pq.status = 'active' AND pq.deadline > %s
    """, (player_id, datetime.now()))
    
    for quest in active_quests:
        if quest["target_type"] == action_type:
            new_progress = quest["progress"] + value
            DB.execute("UPDATE player_quests SET progress = %s WHERE player_id = %s AND quest_id = %s", 
                       (new_progress, player_id, quest["quest_id"]))
            
            if new_progress >= quest["target_count"]:
                # تکمیل مأموریت
                DB.execute("UPDATE player_quests SET status = 'completed', completed_at = NOW() WHERE player_id = %s AND quest_id = %s", 
                           (player_id, quest["quest_id"]))
                
                # اعطای پاداش
                DB.execute("UPDATE players SET coins = coins + %s, experience = experience + %s WHERE player_id = %s", 
                           (quest["reward_coins"], quest["reward_xp"], player_id))
                
                # پاداش آیتم‌ها (اگر وجود داشته باشد)
                if quest["reward_items"]:
                    try:
                        items = json.loads(quest["reward_items"]) if isinstance(quest["reward_items"], str) else quest["reward_items"]
                        for item in items:
                            DB.execute("INSERT INTO inventory (player_id, item_id, quantity) VALUES (%s, %s, %s) ON DUPLICATE KEY UPDATE quantity = quantity + %s", 
                                       (player_id, item["id"], item["qty"], item["qty"]))
                    except:
                        pass
                
                return quest
    return None

def check_completed_quests(player_id):
    """بررسی مأموریت‌های تکمیل شده و ارسال پیام"""
    completed = DB.fetchall("""
        SELECT pq.*, q.title, q.reward_xp, q.reward_coins, q.reward_items
        FROM player_quests pq
        JOIN quests q ON pq.quest_id = q.quest_id
        WHERE pq.player_id = %s AND pq.status = 'completed' AND pq.completed_at > DATE_SUB(NOW(), INTERVAL 1 MINUTE)
    """, (player_id,))
    return completed

def calculate_next_level_xp(level):
    kills_needed = _interpolate_log_linear(XP_KILLS_TABLE, level)
    return int(round(kills_needed * _interpolate_log_linear(REWARD_XP_TABLE, level)))

# --- ۴-۲. اعلان ارتقای سطح ---
def check_level_up(player_id, player_data=None):
    """بررسی و ارسال اعلان ارتقای سطح"""
    player = player_data or DB.fetchone("SELECT level, experience, player_name FROM players WHERE player_id = %s", (player_id,))
    if not player:
        return None
    
    # محاسبه تجربه مورد نیاز برای سطح بعدی (بر اساس تعداد شکار لازم × XP هیولای همان طبقه)
    next_level_xp = calculate_next_level_xp(player["level"])
    if player["experience"] >= next_level_xp:
        new_level = player["level"] + 1
        DB.execute("UPDATE players SET level = %s, experience = experience - %s WHERE player_id = %s", 
                   (new_level, next_level_xp, player_id))
        
        return {
            "old_level": player["level"],
            "new_level": new_level,
            "player_name": player["player_name"]
        }
    return None

def get_level_up_message(old_level, new_level, player_name):
    return f"""🌟 [ ارتقای سطح - Level UP! ] 🌟

🎉 بازیکن {player_name} عزیز، تبریک! سطح شما ارتقا یافت.

📈 سطح: {old_level} ➔ {new_level}

⚔️ شما قدرتمندتر از قبل شده‌اید!"""

# --- ۴-۳. جاسوسی کامل برای پارتنر مقتول ---
def send_partner_spy_report(bot, victim_id, attacker_name, attacker_id, floor, loot_summary):
    """ارسال گزارش جاسوسی کامل به پارتنر مقتول"""
    couple = DB.fetchone("SELECT * FROM couples WHERE player_id_1 = %s OR player_id_2 = %s", (victim_id, victim_id))
    if not couple:
        return
    
    partner_id = couple["player_id_2"] if couple["player_id_1"] == victim_id else couple["player_id_1"]
    partner = DB.fetchone("SELECT player_id, chat_id_pv, server_id FROM players WHERE player_id = %s", (partner_id,))
    if not partner or not partner.get("chat_id_pv"):
        return
    
    report = f"""📊 [ گزارش فوق‌محرمانه: حمله به پارتنر شما ]

⚔️ شریک شما ({DB.fetchone('SELECT player_name FROM players WHERE player_id = %s', (victim_id,))['player_name']}) در طبقه {floor} توسط بازیکن زیر کشته شد:

──────────────────
🎯 شناسه قاتل: {attacker_id}
👤 نام قاتل: {attacker_name}
🏢 طبقه: {floor}
──────────────────
🎒 غنایم غارت شده:
{loot_summary}
──────────────────
💡 برای انتقام، می‌توانید:
🔹 از یک قاتل برای جاسوسی از {attacker_name} کمک بگیرید
🔹 با تشکیل یک تیم تهاجمی، به او حمله کنید
🔹 در گروه‌ها از سایر بازیکنان برای شکار او کمک بخواهید

🩸 انتقام در راه است..."""
    
    asyncio.create_task(send_to_player(bot, partner, report))

# --- ۴-۴. غارت آیتم و حیوان در PvP (به‌روزرسانی) ---
def loot_items_from_player(winner_id, loser_id, bot=None):
    """انتقال آیتم‌ها و حیوانات همراه از بازنده به برنده با گزارش کامل"""
    looted_items = []
    loot_summary = ""
    
    # ۱. غارت آیتم‌های موجود در inventory (نشان اشراف هیچ‌وقت قابل غارت نیست)
    loser_inv = DB.fetchall("""
        SELECT inv.item_id, inv.quantity, i.item_name, i.type_id
        FROM inventory inv
        JOIN items i ON inv.item_id = i.item_id
        LEFT JOIN equipment e ON inv.player_id = e.player_id 
            AND (inv.item_id = e.weapon_id OR inv.item_id = e.armor_id OR inv.item_id = e.pet_id)
        WHERE inv.player_id = %s AND e.player_id IS NULL AND inv.item_id != 4
    """, (loser_id,))
    
    for item in loser_inv:
        if random.random() < 0.25:
            qty = max(1, int(item["quantity"] * 0.25))
            DB.execute("UPDATE inventory SET quantity = quantity - %s WHERE player_id = %s AND item_id = %s", (qty, loser_id, item["item_id"]))
            DB.execute("DELETE FROM inventory WHERE player_id = %s AND item_id = %s AND quantity <= 0", (loser_id, item["item_id"]))
            DB.execute("INSERT INTO inventory (player_id, item_id, quantity) VALUES (%s, %s, %s) ON DUPLICATE KEY UPDATE quantity = quantity + %s", (winner_id, item["item_id"], qty, qty))
            looted_items.append(f"{item['item_name']} x{qty}")
    
    # ۲. غارت حیوان همراه
    loser_equip = DB.fetchone("SELECT pet_id FROM equipment WHERE player_id = %s", (loser_id,))
    if loser_equip and loser_equip["pet_id"]:
        if random.random() < 0.15:
            pet_id = loser_equip["pet_id"]
            DB.execute("UPDATE equipment SET pet_id = NULL WHERE player_id = %s", (loser_id,))
            DB.execute("INSERT INTO inventory (player_id, item_id, quantity) VALUES (%s, %s, 1) ON DUPLICATE KEY UPDATE quantity = quantity + 1", (winner_id, pet_id, 1))
            pet_name = DB.fetchone("SELECT item_name FROM items WHERE item_id = %s", (pet_id,))
            if pet_name:
                looted_items.append(f"🐾 {pet_name['item_name']}")
    
    if looted_items:
        loot_summary = "\n".join(f"🔸 {item}" for item in looted_items)
    else:
        loot_summary = "❌ هیچ آیتمی غارت نشد"
    
    return looted_items, loot_summary

