                STATES[user_guid]["gender"] = gender
                STATES[user_guid]["state"] = "REG_CLASS"
                class_keypad = ChatKeypadBuilder().row(
                    ChatKeypadBuilder().button(id="warrior", text="⚔️ جنگجو 🛡"),
                    ChatKeypadBuilder().button(id="merchant", text="⚖️ تاجر")
                ).row(
                    ChatKeypadBuilder().button(id="blacksmith", text="⚒️ آهنگر"),
                    ChatKeypadBuilder().button(id="assassin", text="🥷 قاتل")
                ).row(
                    ChatKeypadBuilder().button(id="warlord", text="🎖 فرمانده")
                ).build()
