            STATES.pop(user_guid, None)
            success_text = (
                "🏰«دروازه‌های نقره‌ای با صدایی آرام باز می‌شوند و نسیم گرمی به صورتت می‌وزد... 🍃\n\n"
                "به شهر شروع (طبقه اول کاردینال) خوش آمدی! این طبقه تحت طلسم محافظت ابدی است؛ اینجا یک منطقه‌ی کاملاً امن (Safe Zone) است و هیچ جنگجویی نمی‌تواند سلاح خود را به روی دیگری بکشد.\n\n"
                "با خیال راحت کوله‌پشتی‌ات را بررسی کن، تجهیزاتت را لمس کن و با اهالی شهر قدم بزن. خودت را برای روزهای سخت‌تر در طبقات بالاتر آماده کن، مسافر!»\n\n"
                f"🎁 هدیه ورود شما: +۲۰۰ سکه کاردینالت به موجودی شما اضافه شد."
            )
