                pvp_cancel_key = ChatKeypadBuilder().row(ChatKeypadBuilder().button(id="cancel_pvp", text="🔙 لغو و بازگشت به منو")).build()
                if not target_id.isdigit():
                    await message.reply_keypad("❌ شناسه باید فقط عدد باشد. مجدداً شناسه کاردینال معتبری ارسال کنید یا عملیات را لغو کنید:", pvp_cancel_key)
