                    "`/add_item [نام] [نوع(1-4)] [قیمت_سکه] [قیمت_ریال]`\n"
                    "مثال: `/add_item شمشیر آتشین 1 500 0`\n\n"
                    "برای تغییر وضعیت آیتم:\n"
