                    "لیست شناسه‌های شغل:\n"
                    f"{classes_text}\n\n"
                    "برای تغییر شغل، دستور را به این شکل ارسال کنید:\n"
                    "`/set_class [شناسه کاردینال بازیکن] [شناسه شغل]`\n\n"
